WITH exploded AS (SELECT id, service, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v), unpacked AS (SELECT id, service, latency_ms, key, v, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 4) != 0 AS INT) AS has_fault FROM exploded), scored AS (SELECT *, LEAD(status_code_high) OVER w_grp AS next_status_code_high, LAG(has_fault) OVER w_grp AS prev_has_fault, LEAD(has_fault) OVER w_grp AS next_has_fault, ROW_NUMBER() OVER w_grp AS row_seq FROM unpacked WHERE service IN ('checkout', 'billing', 'auth') WINDOW w_grp AS (PARTITION BY key ORDER BY latency_ms, id, key)), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY service ORDER BY has_fault NULLS FIRST, id, key) AS rank_in_group FROM scored) ranked WHERE rank_in_group = 1) SELECT service, key, SIZE(COLLECT_SET(service)) AS num_services, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(*) AS num_rows FROM ranked GROUP BY service, key ORDER BY key;
